fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Since it's guaranteed that `a.len() == b.len()` and no element of `b` is zero,
    // we can simply zip the two vectors and compute the remainder for each pair.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x % y)
     .collect()
}

fn main() {
    // Example usage:

    let a = vec![10, 23, -5, 0];
    let b = vec![3, 5, 4, 7];
    let result = element_wise_modulo(a, b);
    assert_eq!(result, vec![1, 3, -1, 0]);

    let empty_a: Vec<i32> = vec![];
    let empty_b: Vec<i32> = vec![];
    let empty_result = element_wise_modulo(empty_a, empty_b);
    assert!(empty_result.is_empty());

    println!("All tests passed!");
}